custom_css:
::selection { background: rgba(229, 31, 72, 0.3); color: var(--fg); }

[data-theme="halftone-dimension"] .bg-accent { box-shadow: 0 0 20px rgba(229, 31, 72, 0.4), 0 0 40px rgba(229, 31, 72, 0.15); }

[data-theme="halftone-dimension"] .assistant-bubble { border-left: 3px solid #E51F48; }

[data-theme="halftone-dimension"] .header-bar { border-color: rgba(229, 31, 72, 0.4); }
[data-theme="halftone-dimension"] .input-bar-container { border-color: rgba(229, 31, 72, 0.4); }

[data-theme="halftone-dimension"] button:focus-visible, [data-theme="halftone-dimension"] a:focus-visible, [data-theme="halftone-dimension"] select:focus-visible { outline: 2px solid #E51F48; outline-offset: 2px; box-shadow: 0 0 8px rgba(229, 31, 72, 0.3); }

[data-theme="halftone-dimension"] h1,
[data-theme="halftone-dimension"] h2,
[data-theme="halftone-dimension"] .header-bar { text-shadow: -1.5px 0 rgba(229, 31, 72, 0.4), 1.5px 0 rgba(0, 184, 255, 0.4); }

[data-theme="halftone-dimension"] .user-bubble { box-shadow: 0 0 18px rgba(229, 31, 72, 0.3), 0 0 40px rgba(229, 31, 72, 0.1); border: 1.5px solid rgba(229, 31, 72, 0.5); }

::-webkit-scrollbar-thumb { background-image: url('assets/scrollbar-thumb.svg'); background-size: contain; background-repeat: repeat-y; }
::-webkit-scrollbar-track { background: transparent; }
